import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { useCallback, useEffect, useState } from "react"

import { useAuth } from "@/domains/platform/auth"

import {
  fetchSessionDetailFilterPreference,
  saveSessionDetailFilterPreference,
  type SessionDetailFilterPreferenceResponse,
} from "../api"
import {
  getDefaultSessionDetailFilters,
  type FilterState,
  type SessionDetailPreference,
} from "../components/sessionFilters"

export const SESSION_DETAIL_FILTER_PREFERENCE_QUERY_KEY = [
  "preferences",
  "session-detail-filters",
] as const

type SaveStatus = "idle" | "saved" | "error"

function normalizeFilterDefaults(
  filters: SessionDetailFilterPreferenceResponse["filters"] | undefined,
): FilterState | null {
  if (!filters) {
    return null
  }

  const defaults = getDefaultSessionDetailFilters()
  const normalized: FilterState = {
    prompts: filters.prompts,
    responses: filters.responses,
    intermediateSteps: filters.intermediateSteps,
    checkpoints: filters.checkpoints,
    toolCalls: filters.toolCalls,
    toolCategories: {
      "File edits": filters.toolCategories["File edits"] ?? defaults.toolCategories["File edits"],
      Bash: filters.toolCategories.Bash ?? defaults.toolCategories.Bash,
      Read: filters.toolCategories.Read ?? defaults.toolCategories.Read,
      Skills: filters.toolCategories.Skills ?? defaults.toolCategories.Skills,
      Other: filters.toolCategories.Other ?? defaults.toolCategories.Other,
    },
  }

  const hasTopLevelFilter =
    normalized.prompts ||
    normalized.responses ||
    normalized.intermediateSteps ||
    normalized.checkpoints ||
    normalized.toolCalls
  const hasToolCategory = Object.values(normalized.toolCategories).some(Boolean)

  if (!hasTopLevelFilter || (normalized.toolCalls && !hasToolCategory)) {
    return null
  }

  return normalized
}

export function useSessionDetailFilterPreference() {
  const { isAuthenticated } = useAuth()
  const queryClient = useQueryClient()
  const [saveStatus, setSaveStatus] = useState<SaveStatus>("idle")

  const preferenceQuery = useQuery({
    queryKey: SESSION_DETAIL_FILTER_PREFERENCE_QUERY_KEY,
    queryFn: fetchSessionDetailFilterPreference,
    enabled: isAuthenticated,
    staleTime: Infinity,
  })

  const { mutate: savePreference, isPending: isSavingPreference } = useMutation({
    mutationFn: saveSessionDetailFilterPreference,
    onMutate: async () => {
      setSaveStatus("idle")
      await queryClient.cancelQueries({ queryKey: SESSION_DETAIL_FILTER_PREFERENCE_QUERY_KEY })
    },
    onSuccess: (data) => {
      queryClient.setQueryData<SessionDetailFilterPreferenceResponse>(
        SESSION_DETAIL_FILTER_PREFERENCE_QUERY_KEY,
        data,
      )
      setSaveStatus("saved")
    },
    onError: () => {
      setSaveStatus("error")
    },
  })

  useEffect(() => {
    if (saveStatus === "idle") {
      return
    }

    const timeout = window.setTimeout(() => setSaveStatus("idle"), 2000)
    return () => window.clearTimeout(timeout)
  }, [saveStatus])

  const saveDefaultFilters = useCallback(
    (preference: SessionDetailPreference) => savePreference(preference),
    [savePreference],
  )

  return {
    defaultFilters: normalizeFilterDefaults(preferenceQuery.data?.filters),
    defaultShowHiddenIndicators: preferenceQuery.data?.showHiddenIndicators ?? null,
    canSaveDefaultFilters: isAuthenticated,
    saveDefaultFilters,
    isSavingDefaultFilters: isSavingPreference,
    saveDefaultFiltersStatus: saveStatus,
  }
}

