      commit_sha: row.commit_sha,
      commit_message: row.commit_message ?? null,
      commit_author_username: row.commit_author_username ?? null,
      additions: row.additions ?? null,
      deletions: row.deletions ?? null,
      files_changed: row.files_changed ?? null,
      commit_date: normalizeCommitDate(row.commit_date),
    })
  }

  return orderedCheckpoints
    .map((row) => {
      const payload = payloadById.get(row.checkpoint_id)
      const commit = commitByCheckpoint.get(row.checkpoint_id)
      return {
        checkpoint_id: row.checkpoint_id,
        sessions: normalizeJsonColumnString(payload?.sessions),
        transcript_stripped: normalizeJsonColumnString(payload?.transcript_stripped),
        payload_hydration_state: parsePayloadHydrationState(payload?.payload_hydration_state),
        storage_version: payload?.storage_version ?? null,
        should_load_transcript: shouldLoadTranscriptIds.has(row.checkpoint_id),
        dead_session_indices: payload?.dead_session_indices ?? null,
        rawSessions: payload?.sessions,
        commit_sha: commit?.commit_sha ?? null,
        commit_message: commit?.commit_message ?? null,
        commit_author_username: commit?.commit_author_username ?? null,
        additions: commit?.additions ?? null,
        deletions: commit?.deletions ?? null,
        files_changed: commit?.files_changed ?? null,
        // Fallback to the ordering-query date when the commit metadata query
        // didn't find a row — go through the same normalizer so the `Date`
        // that mysql2 hands us for `MIN(rc.commit_date)` doesn't leak out.
        commit_date: commit?.commit_date ?? normalizeCommitDate(row.commit_date),
      }
    })
    .filter((row) => {
      const dead = row.dead_session_indices
      if (!dead || dead.length === 0) return true
