// Admin: Clear transcript cache by org and/or repo
// Supports: orgName (clears all repos in org), repoFullName (clears specific repo), all (clears everything)
adminRoutes.post("/clear-transcript-cache", async (c) => {
  const body = await c.req.json<{
    orgName?: string
    repoFullName?: string
    all?: boolean
  }>()
  const { orgName, repoFullName, all } = body

  if (orgName && !isValidGitHubOrgName(orgName)) {
    return c.json({ error: "Invalid organization name format" }, 400)
  }

  const transcriptPrefix = buildTranscriptCachePrefix({ orgName, repoFullName, all })
  const sessionPrefix = buildSessionTranscriptCachePrefix({ orgName, repoFullName, all })
  if (!transcriptPrefix || !sessionPrefix) {
    return c.json({ error: "Must specify orgName, repoFullName, or all" }, 400)
  }

  const [transcriptDeleted, sessionDeleted] = await Promise.all([
    clearTranscriptCacheByPrefix(c.env.ENTIRE_CACHE, transcriptPrefix),
    clearTranscriptCacheByPrefix(c.env.ENTIRE_CACHE, sessionPrefix),
  ])
  const deletedCount = transcriptDeleted + sessionDeleted

  const scope = repoFullName
    ? `repo "${repoFullName}"`
    : orgName
      ? `org "${orgName}"`
      : "all transcripts"

  return c.json({
    success: true,
    message: `Cleared ${deletedCount} transcript cache entries for ${scope}`,
    deleted: deletedCount,
    prefixes: [transcriptPrefix, sessionPrefix],
  })
})

