// R2-backed storage for stripped transcripts.
//
// Layout:
//   transcripts/{repo_id}/{checkpoint_id}/{session_id}.jsonl
//
// One R2 object per session, keyed by the session_id (UUID-ish) recorded in
// the checkpoint's metadata.json. Per-session metadata (ref, path, filename)
// lives in R2 custom metadata so the StoredTranscriptSessions envelope can be
// reconstructed on read without a sidecar.
//
// `sessionId` is expected on every new write but is typed optional on
// `SessionInfo` (api/src/types.ts) for backwards compatibility with rows
// written before that field existed. Sparse handling defends against those
// rows: we drop the missing entry rather than failing the whole checkpoint.
// Legacy bulk data (pre-R2) lives in `repo_checkpoint_transcripts
// .transcript_stripped` and is served by the PS-first read path; the R2 key
// is never constructed for those rows.

import {
  type StoredTranscriptSession,
  serializeStoredTranscriptSessions,
} from "./stored-transcript"

const KEY_PREFIX = "transcripts"

// Bound on concurrent R2 GETs from a single envelope read. A checkpoint can
// have many sessions and several checkpoints can read in parallel (search
// indexer batches, hydrator fan-out) — left unbounded, that easily issues
// hundreds of simultaneous GETs.
// Workers allow at most ~6 simultaneous open connections per invocation, and an
// unconsumed R2 object body holds a connection open. Keep this under that limit
// (with headroom for the request's other connections, e.g. Hyperdrive) so a
// multi-session checkpoint read never trips "Response closed due to connection
// limit". See readEnvelopeFromR2 — each stream is consumed before the next opens.
const R2_READ_CONCURRENCY = 5

export function transcriptKey(repoId: string, checkpointId: string, sessionId: string): string {
  return `${KEY_PREFIX}/${repoId}/${checkpointId}/${sessionId}.jsonl`
}

/** R2 key prefix scoping every transcript object for a single repo. */
export function repoTranscriptPrefix(repoId: string): string {
  return `${KEY_PREFIX}/${repoId}/`
}

/**
 * Extract the session_ids for a checkpoint in array-order. Accepts either the
 * already-parsed SessionInfo[] (when the DB client has unmarshalled the JSON
 * column for us) or the raw JSON string.
 *
 * Returns a sparse array — entries without `sessionId` become `null` so the
 * envelope reconstruction can preserve index alignment while still reading R2
 * for the sessions that DO have ids. Returns `[]` only when the input is
 * malformed (not an array, not parseable). New data always has every
 * `sessionId` populated per the CommittedMetadata contract; the sparse handling
 * is defense for partial-metadata edge cases.
 */
export function extractSessionIds(sessions: unknown): (string | null)[] {
  if (!sessions) return []
  let arr: unknown = sessions
  if (typeof sessions === "string") {
    try {
      arr = JSON.parse(sessions)
    } catch (err) {
      // A corrupt `sessions` column looks identical to "no sessions" to
      // every caller, which silently disables R2 transcript reads for the
      // affected checkpoint. Surface the row so it's investigable.
      console.warn(
        "[transcript-r2] extractSessionIds: malformed JSON in sessions column",
        err instanceof Error ? err.message : String(err),
      )
      return []
    }
  }
  if (!Array.isArray(arr)) return []
  return arr.map((entry) => {
    const id = (entry as { sessionId?: unknown } | null | undefined)?.sessionId
    return typeof id === "string" && id.length > 0 ? id : null
  })
}

/**
 * Write each session as its own R2 object. The `sessions` map's keys are
 * session_ids (not indices); each value carries ref/path/filename in R2 custom
 * metadata for envelope reconstruction on read.
 */
export async function writeCheckpointTranscriptToR2(
  bucket: R2Bucket,
  repoId: string,
  checkpointId: string,
  sessions: Record<string, StoredTranscriptSession>,
): Promise<void> {
  const entries = Object.entries(sessions)
  if (entries.length === 0) return

  await Promise.all(
    entries.map(([sessionId, session]) => {
      const customMetadata: Record<string, string> = {}
      if (session.ref) customMetadata.ref = session.ref
      if (session.path) customMetadata.path = session.path
      if (session.filename) customMetadata.filename = session.filename
      return bucket.put(transcriptKey(repoId, checkpointId, sessionId), session.content, {
        httpMetadata: { contentType: "application/x-ndjson" },
        customMetadata,
      })
    }),
  )
}

/**
 * Reconstruct the StoredTranscriptSessions envelope from per-session R2
 * objects. Returns the envelope keyed by index (preserving the shape the rest
 * of the codebase expects) — sessionIds are the R2 lookup key, not the
 * envelope key.
 *
 * Tolerant of missing objects: a session whose transcript file was dead at
 * hydration time has no R2 object, but the rest of the checkpoint should
 * still be readable. Returns null only when no session yielded an object —
 * that's the signal callers use to fall back to inline content.
 */
async function readEnvelopeFromR2(
  bucket: R2Bucket,
  repoId: string,
  checkpointId: string,
  sessionIds: (string | null)[],
): Promise<string | null> {
  // Fetch AND fully read each object within the same bounded step. Reading the
  // body (.text()) immediately releases the R2 connection, so we never hold
  // more than R2_READ_CONCURRENCY open at once. The previous two-phase approach
  // (get every object, THEN read every body) kept all of a checkpoint's session
  // streams open simultaneously; on multi-session checkpoints (e.g. 16 sessions)
  // that exceeded the Workers simultaneous-open-connection limit and surfaced as
  // "Response closed due to connection limit", failing the whole read and
  // rendering the transcript empty.
  //
  // Slots with a null id (partial metadata) stay null so the envelope still
  // aligns by original index for whatever sessions DO have R2 objects.
  const sessionsByIndex = await mapWithConcurrency(
    sessionIds,
    R2_READ_CONCURRENCY,
    async (sessionId): Promise<StoredTranscriptSession | null> => {
      if (!sessionId) return null
      const obj = await bucket.get(transcriptKey(repoId, checkpointId, sessionId))
      if (!obj) return null
      const session: StoredTranscriptSession = { content: await obj.text() }
      if (obj.customMetadata?.ref) session.ref = obj.customMetadata.ref
      if (obj.customMetadata?.path) session.path = obj.customMetadata.path
      if (obj.customMetadata?.filename) session.filename = obj.customMetadata.filename
      return session
    },
  )

  const sessions: Record<string, StoredTranscriptSession> = {}
  for (let i = 0; i < sessionsByIndex.length; i++) {
    const session = sessionsByIndex[i]
    if (session) sessions[String(i)] = session
  }
  if (Object.keys(sessions).length === 0) return null
  return serializeStoredTranscriptSessions(sessions)
}

/**
 * Resolve transcript content for a checkpoint. PlanetScale-first: when the
 * caller already has inline `transcript_stripped` from the row (legacy data,
 * written before R2 existed), return it directly. Only fetch from R2 when the
 * caller has no inline content — that's the path checkpoints written after
 * the R2 layout existed take.
 *
 * Returns `null` when no content is available from any source. THROWS when an
 * R2 read fails — callers must distinguish a real outage from genuinely empty
 * content. Returning null here would make a transient R2 outage look identical
 * to "no R2 object exists", causing the search indexer (and others) to
 * redundantly re-fetch from GitHub and re-write to R2.
 */
export async function readCheckpointTranscript(
  bucket: R2Bucket | undefined,
  repoId: string,
  checkpointId: string,
  sessionIds: (string | null)[],
  inlineContent: string | null,
): Promise<string | null> {
  if (inlineContent) return inlineContent
  if (!bucket || sessionIds.every((id) => id === null)) return null
  return await readEnvelopeFromR2(bucket, repoId, checkpointId, sessionIds)
}

// Run an async mapper over items with at most `limit` in-flight concurrent
// operations. Preserves input order in the output array. Kept local to this
// file to avoid a dependency on a wider concurrency helper.
async function mapWithConcurrency<T, R>(
  items: readonly T[],
  limit: number,
  fn: (item: T, idx: number) => Promise<R>,
): Promise<R[]> {
  const results: R[] = new Array(items.length)
  let cursor = 0
  const workers = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, async () => {
    while (true) {
      const idx = cursor++
      if (idx >= items.length) return
      results[idx] = await fn(items[idx], idx)
    }
  })
  await Promise.all(workers)
  return results
}

