const SESSION_ID_PATTERN = /^[a-zA-Z0-9._-]{1,128}$/

type SessionAccessMode = "authorized" | "public"

// Unified access gate for session-scoped endpoints.
//   authorized → authenticated repo member (or admin via user_repos).
//   public     → anyone else, when the session is publicly viewable:
//                  - public GitHub repo (always public), OR
//                  - private repo with `public_sharing_enabled` AND a
//                    per-session share row in `session_shares`.
// Anything else collapses to a 404 Response.
async function resolveSessionAccess(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  db: Db,
  opts: { repoFullName: string; sessionId: string; userId: string | undefined },
): Promise<{ repo: Repo; mode: SessionAccessMode; isShared: boolean } | Response> {
  const { repoFullName, sessionId, userId } = opts

  if (userId) {
    const access = await db.repos.getByFullNameWithAccess(repoFullName, userId)
    if (access.status === "found") {
      // Authorized members always need `isShared` for the toggle UI state and
      // for the storage-repo gate bypass below — sharing is meaningful for
      // public repos with separate private storage too, not only private repos.
      const isShared = await db.sessionShares.isShared(access.repo.id, sessionId)
      return { repo: access.repo, mode: "authorized", isShared }
    }
  }

  const repo = await db.repos.getByFullName(repoFullName)
  if (!repo) return c.json({ error: "Not found" }, 404)

  if (!repo.is_private) {
    // Public source: anyone can hit the route, but a share row may still be
    // load-bearing when the storage repo is separate-private. Resolve it so
    // the transcript route can bypass the storage-repo gate for shared
    // sessions, and so the response carries the right `isShared` state.
    const isShared = await db.sessionShares.isShared(repo.id, sessionId)
    return { repo, mode: "public", isShared }
  }

  if (repo.public_sharing_enabled) {
    const isShared = await db.sessionShares.isShared(repo.id, sessionId)
    if (isShared) return { repo, mode: "public", isShared: true }
  }

  return c.json({ error: "Not found" }, 404)
}

