function markTrailChecksPendingAfterBranchUpdate(
  previous: TrailChecksStatus | undefined,
  headSha: string,
): TrailChecksStatus {
  return {
    state: "pending",
    head_sha: headSha,
    total_count: previous?.total_count ?? 0,
    checks: previous ? markChecksPendingAfterBranchUpdate(previous.checks) : [],
    ci_pr: previous?.ci_pr,
    automation: previous?.automation ?? null,
  }
}

function markMergeabilityPendingAfterBranchUpdate(
  previous: TrailMergeability | undefined,
): TrailMergeability | undefined {
  if (!previous) return previous

  return {
    ...previous,
    checks_passed: false,
    checks_status: "pending",
    checks: markChecksPendingAfterBranchUpdate(previous.checks),
    behind_by: 0,
    mergeable: false,
  }
}

export function TrailStatusBox({
  trail,
  org,
  repo,
  number,
  mergeability,
  findings,
  isFindingsLoading,
  isFindingsError,
  checksStatus,
  isChecksLoading,
  isChecksError,
  extraGates,
}: {
  trail: TrailDetail
  org: string
  repo: string
  number: number
  mergeability?: TrailMergeability
  findings?: TrailCodeReviewComment[]
  isFindingsLoading?: boolean
  isFindingsError?: boolean
  checksStatus?: TrailChecksStatus
  isChecksLoading?: boolean
  isChecksError?: boolean
  extraGates?: StatusBoxGate[]
}) {
  const queryClient = useQueryClient()
  const trailChecksQueryKey = ["github", "trail-checks", org, repo, number]
  const mergeabilityQueryKey = ["github", "trails", org, repo, number, "mergeability"]
  const updateBranchMutation = useMutation({
    mutationFn: () => updateTrailBranch(org, repo, number),
    onSuccess: (result) => {
      // request() casts the response without runtime validation, so guard
      // against a missing/empty (or non-string) body — never feed an undefined
      // SHA into the cache. The onSettled invalidation refetches authoritative
      // state anyway.
      const mergeCommitSha =
        typeof result?.merge_commit_sha === "string" ? result.merge_commit_sha.trim() : ""
      if (!mergeCommitSha) return

      queryClient.setQueryData<TrailChecksStatus>(trailChecksQueryKey, (previous) =>
        markTrailChecksPendingAfterBranchUpdate(previous, mergeCommitSha),
      )
      queryClient.setQueryData<TrailMergeability>(mergeabilityQueryKey, (previous) =>
        markMergeabilityPendingAfterBranchUpdate(previous),
      )
    },
    onSettled: () => {
      queryClient.invalidateQueries({
        queryKey: ["github", "trails", org, repo, number],
      })
      queryClient.invalidateQueries({
        queryKey: mergeabilityQueryKey,
      })
      queryClient.invalidateQueries({
        queryKey: ["github", "trails", org, repo, "compare"],
      })
      queryClient.invalidateQueries({
        queryKey: trailChecksQueryKey,
      })
    },
  })
  const gates = getStatusBoxGates({
    trail,
    mergeability,
    findings,
    isFindingsLoading,
    isFindingsError,
    checksStatus,
    isChecksLoading,
    isChecksError,
    extraGates,
    onUpdateBranch: () => updateBranchMutation.mutate(),
    isUpdatingBranch: updateBranchMutation.isPending,
    updateBranchErrorMessage: updateBranchMutation.isError
      ? updateBranchMutation.error?.message || "Failed to update branch"
      : null,
  })

  useFavicon(getTrailFaviconHref(gates))

  return <StatusBoxGates gates={gates} padded={false} title="Gates" />
}

