  checkpointShas: string[],
): Promise<CheckpointPayloadCommit[]> {
  const rows = await db.checkpoints.getRepoCommitsByShas(repoId, checkpointShas)
  const rowsBySha = new Map(rows.map((commit) => [commit.commit_sha, commit]))
  const commits = checkpointShas
    .map((sha) => rowsBySha.get(sha))
    .filter((commit): commit is RepoCommitData => commit !== undefined)

  if (commits.length !== checkpointShas.length) {
    const missingShas = checkpointShas.filter((sha) => !rowsBySha.has(sha))
    log("checkpoint_commit_hydration_missing", {
      repoId,
      requested: checkpointShas.length,
      found: commits.length,
      missingShas: missingShas.slice(0, 20),
